/**
 * Division Gap Filler — Generates one rich entity per missing division.
 * Run: npx tsx scripts/generate-gap-entities.ts
 * Output: Writes to ../src/data/catalog/divisionGapFill.ts
 */
import { DIVISIONS } from '../src/constants/callNumbers.ts';
import { ALL_CATALOG_ENTITIES } from '../src/data/catalog/index.ts';
import * as fs from 'fs';
import * as path from 'path';

// Get covered divisions
const coveredDivs = new Set<string>();
ALL_CATALOG_ENTITIES.forEach(e => {
  const cn = e.callNumber || '';
  const m = cn.match(/^(\d{3})\./);
  if (m) coveredDivs.add(m[1]);
});

// Get existing slugs
const existingSlugs = new Set(ALL_CATALOG_ENTITIES.map(e => e.slug));

// Missing divisions
const missing = DIVISIONS.filter(d => !coveredDivs.has(d.code));

console.log(`Generating entities for ${missing.length} missing divisions...`);

interface GapEntity {
  code: string;
  heading: string;
  parentClass: number;
  slug: string;
  name: string;
  label: string;
  era: string;
  summary: string;
  causes: string[];
  effects: string[];
  places: string[];
  frameworks: string[];
}

// Label mapping by class
function labelForClass(cls: number): string {
  switch (cls) {
    case 0: case 1: return 'Idea';
    case 2: return 'Person';
    case 3: return 'Institution';
    case 4: return 'Place';
    case 5: return 'EventWindow';
    case 6: return 'Movement';
    case 7: return 'Text';
    case 8: return 'Evidence';
    case 9: return 'EventWindow';
    default: return 'EventWindow';
  }
}

// Define entity data for each missing division
const entityDefs: Record<string, Omit<GapEntity, 'code' | 'heading' | 'parentClass'>> = {
  // Class 0 — Ideas (Core)
  '013': { slug: 'federalism-concept', name: 'Federalism & Confederalism', label: 'Idea', era: 'Early Modern', summary: 'The principle of dividing sovereignty between a central authority and constituent political units. Federalism emerged as a practical compromise between unitary states and loose confederations, enabling diverse communities to share governance while retaining local autonomy. The American, Swiss, and German federal systems became models studied worldwide.', causes: ['Tensions between centralized authority and regional autonomy', 'Failure of confederal arrangements like the Articles of Confederation'], effects: ['Enabled governance of large, diverse territories', 'Influenced constitutional design in dozens of nations'], places: ['United States', 'Switzerland', 'Germany'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '014': { slug: 'theocracy-concept', name: 'Theocracy & Divine Rule', label: 'Idea', era: 'Classical', summary: 'A system of government in which religious leaders or divine law constitutes the governing authority. From ancient Egyptian pharaohs claiming divine status to the Papal States and Calvin\'s Geneva, theocratic governance has shaped legal codes, social hierarchies, and political legitimacy across civilizations.', causes: ['Religious authority intertwined with political power', 'Belief in divine mandate as source of legitimacy'], effects: ['Shaped legal systems based on religious law', 'Influenced debates on separation of church and state'], places: ['Egypt', 'Vatican City', 'Geneva'], frameworks: ['Comparative Religion', 'Political Systems'] },
  '025': { slug: 'social-contract-idea', name: 'Social Contract Theory', label: 'Idea', era: 'Early Modern', summary: 'The philosophical concept that legitimate political authority rests on an agreement among individuals to form a society and government. Developed by Hobbes, Locke, and Rousseau, social contract theory provided the intellectual foundation for democratic revolutions and modern constitutional governance.', causes: ['Challenges to divine right of kings', 'Enlightenment emphasis on individual rights'], effects: ['Provided philosophical basis for American and French Revolutions', 'Shaped modern democratic constitutions'], places: ['England', 'France', 'United States'], frameworks: ['Cause & Effect', 'Political Systems'] },
  '030': { slug: 'legal-systems-overview', name: 'Legal Systems & Law', label: 'Idea', era: 'Classical', summary: 'The organized body of rules and principles governing human conduct within a society, enforced by institutional authority. From the Code of Hammurabi to contemporary international law, legal systems represent humanity\'s ongoing effort to codify justice, resolve disputes, and maintain social order across diverse civilizations.', causes: ['Need for conflict resolution in complex societies', 'Emergence of centralized states requiring codified rules'], effects: ['Enabled large-scale social cooperation', 'Created frameworks for international relations'], places: ['Mesopotamia', 'Rome', 'England'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '033': { slug: 'canon-law-concept', name: 'Religious & Canon Law', label: 'Idea', era: 'Medieval', summary: 'The body of laws and regulations made by ecclesiastical authority for the governance of a religious organization and its members. Canon law developed most extensively in the Catholic Church, creating a parallel legal system that governed marriage, inheritance, education, and clerical conduct across medieval Europe.', causes: ['Need to govern growing church institutions', 'Precedent from Roman legal traditions'], effects: ['Influenced development of European civil law', 'Established principles of due process in ecclesiastical courts'], places: ['Rome', 'France', 'England'], frameworks: ['Doctrine Development', 'Institutional Analysis'] },
  '034': { slug: 'customary-law-traditions', name: 'Customary & Indigenous Law', label: 'Idea', era: 'Prehistoric', summary: 'Legal systems based on long-established customs, practices, and oral traditions of indigenous and local communities. Predating written law, customary law governed land tenure, marriage, dispute resolution, and resource management across Africa, Oceania, the Americas, and Asia for millennia.', causes: ['Oral tradition as primary means of social regulation', 'Community consensus as basis for justice'], effects: ['Influenced post-colonial legal frameworks in Africa and Asia', 'Ongoing debates on integration with formal legal systems'], places: ['Sub-Saharan Africa', 'Australia', 'Pacific Islands'], frameworks: ['Cultural Diffusion', 'Comparative Religion'] },
  '036': { slug: 'constitutional-law-concept', name: 'Constitutional Law', label: 'Idea', era: 'Modern', summary: 'The body of law that defines the relationship between different entities within a state — the executive, legislature, judiciary, and citizens. Constitutional law establishes fundamental rights, limits government power, and provides the framework for democratic governance.', causes: ['Magna Carta and parliamentary traditions', 'Enlightenment philosophy on natural rights'], effects: ['Foundation of modern democratic states', 'Judicial review as check on government power'], places: ['United States', 'France', 'India'], frameworks: ['Political Systems', 'Cause & Effect'] },

  // Class 1 — Ideas (Other)
  '110': { slug: 'economic-theory-overview', name: 'Economic Theories & Systems', label: 'Idea', era: 'Early Modern', summary: 'The systematic study of production, distribution, and consumption of goods and services. From Adam Smith\'s invisible hand to Keynesian macroeconomics and modern behavioral economics, economic theories have shaped government policies, international trade, and the material conditions of billions.', causes: ['Mercantile expansion and colonial trade networks', 'Need to understand market dynamics and wealth creation'], effects: ['Shaped national economic policies worldwide', 'Influenced debates on capitalism vs socialism'], places: ['Scotland', 'England', 'United States'], frameworks: ['Economic Systems', 'Cause & Effect'] },
  '115': { slug: 'agricultural-economics', name: 'Agricultural & Land Economics', label: 'Idea', era: 'Early Modern', summary: 'Economic theories concerning land use, agricultural production, and rural development. From the Physiocrats who argued land was the source of all wealth, to modern debates on food security and sustainable agriculture, this field addresses how societies feed themselves and distribute land resources.', causes: ['Physiocratic emphasis on land as source of wealth', 'Enclosure movements transforming land tenure'], effects: ['Influenced land reform movements globally', 'Shaped modern agricultural policy and food security'], places: ['France', 'England', 'India'], frameworks: ['Economic Systems', 'Environmental History'] },
  '124': { slug: 'chemistry-alchemy-ideas', name: 'Chemistry & Alchemy', label: 'Idea', era: 'Medieval', summary: 'The evolution from alchemical pursuits of transmutation and the philosopher\'s stone to the systematic science of chemistry. Arabic alchemists preserved and advanced Greek chemical knowledge, while Lavoisier\'s oxygen theory and Mendeleev\'s periodic table transformed alchemy into modern chemistry.', causes: ['Greek theories of four elements', 'Arabic preservation and advancement of chemical knowledge'], effects: ['Foundation of modern pharmaceutical industry', 'Enabled materials science and industrial chemistry'], places: ['Baghdad', 'Paris', 'England'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '126': { slug: 'medicine-public-health-idea', name: 'Medicine & Public Health', label: 'Idea', era: 'Modern', summary: 'The development of medical knowledge from Hippocratic observation through germ theory to modern evidence-based medicine. Public health as a discipline emerged from responses to cholera epidemics, establishing that collective action — sanitation, vaccination, quarantine — could prevent disease at population scale.', causes: ['Germ theory of disease', 'Cholera epidemics revealing failures of urban sanitation'], effects: ['Dramatic increase in human life expectancy', 'Establishment of public health infrastructure worldwide'], places: ['London', 'Paris', 'Berlin'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '131': { slug: 'agricultural-technology-idea', name: 'Agricultural Technology', label: 'Idea', era: 'Prehistoric', summary: 'The application of tools, techniques, and knowledge to increase agricultural productivity. From the earliest digging sticks and irrigation channels of the Fertile Crescent to the Green Revolution\'s high-yield varieties and modern precision agriculture, technological innovation in farming has been humanity\'s most consequential material achievement.', causes: ['Neolithic transition from foraging to farming', 'Population pressure demanding increased food production'], effects: ['Enabled sedentary civilizations and urbanization', 'Green Revolution prevented predicted mass famines'], places: ['Fertile Crescent', 'China', 'Mexico'], frameworks: ['Innovation & Technology', 'Environmental History'] },
  '132': { slug: 'manufacturing-industrial-tech', name: 'Manufacturing & Industrial Technology', label: 'Idea', era: 'Modern', summary: 'The systematic application of machinery, power sources, and organizational methods to mass production. From early watermills and textile looms to assembly lines and robotic automation, industrial technology transformed economies from agrarian to manufacturing-based, reshaping societies worldwide.', causes: ['Steam engine development by Watt', 'Availability of coal and iron resources'], effects: ['Urbanization and rise of factory labor class', 'Exponential increase in material production'], places: ['England', 'United States', 'Germany'], frameworks: ['Innovation & Technology', 'Economic Systems'] },
  '133': { slug: 'transportation-navigation-tech', name: 'Transportation & Navigation Technology', label: 'Idea', era: 'Classical', summary: 'The technologies enabling human movement and wayfinding across land and sea. From Polynesian celestial navigation and Roman road engineering to steamships, railways, and jet aircraft, transportation technology has compressed distance, enabled trade, and connected civilizations.', causes: ['Need for trade route efficiency', 'Military logistics requirements'], effects: ['Enabled global trade networks', 'Accelerated cultural diffusion across continents'], places: ['Polynesia', 'Rome', 'England'], frameworks: ['Innovation & Technology', 'Cultural Diffusion'] },
  '134': { slug: 'communication-information-tech', name: 'Communication & Information Technology', label: 'Idea', era: 'Modern', summary: 'Technologies for transmitting information across distance and time. From the printing press and telegraph to radio, television, and the internet, communication technology has progressively collapsed the barriers of time and space, enabling mass media, democratic participation, and global culture.', causes: ['Gutenberg\'s printing press democratized knowledge', 'Telegraph enabled real-time long-distance communication'], effects: ['Created mass media and public opinion', 'Internet transformed commerce, politics, and social life'], places: ['Germany', 'United States', 'England'], frameworks: ['Innovation & Technology', 'Cultural Diffusion'] },
  '135': { slug: 'military-technology-idea', name: 'Military Technology', label: 'Idea', era: 'Classical', summary: 'The development and application of tools, weapons, and strategies for warfare. From bronze swords and siege engines to gunpowder, nuclear weapons, and cyber warfare, military technology has driven both destruction and innovation, often catalyzing broader technological progress.', causes: ['Competition between states for territorial control', 'Arms races driving rapid innovation'], effects: ['Gunpowder ended feudal warfare in Europe', 'Nuclear weapons created Cold War deterrence paradigm'], places: ['China', 'Europe', 'United States'], frameworks: ['Innovation & Technology', 'Empire & Colonialism'] },
  '136': { slug: 'computing-digital-tech-idea', name: 'Computing & Digital Technology', label: 'Idea', era: 'Contemporary', summary: 'The theoretical and practical development of computational machines from Babbage\'s Analytical Engine through transistor-based computers to modern AI. Digital technology has transformed every aspect of human civilization — communication, commerce, science, warfare, and entertainment.', causes: ['Mathematical foundations by Turing and von Neumann', 'Transistor invention at Bell Labs (1947)'], effects: ['Created the Information Age', 'Enabled artificial intelligence and global connectivity'], places: ['England', 'United States', 'Japan'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '144': { slug: 'mysticism-esotericism', name: 'Mysticism & Esotericism', label: 'Idea', era: 'Medieval', summary: 'Spiritual traditions emphasizing direct, personal experience of the divine or ultimate reality, often through contemplative practices. From Sufi whirling and Kabbalistic meditation to Christian mysticism and Hindu yoga, esoteric traditions have offered alternative paths to knowledge beyond rational inquiry across all major civilizations.', causes: ['Human yearning for direct spiritual experience', 'Limitations of purely rational theological approaches'], effects: ['Enriched spiritual practices across all major religions', 'Influenced Romantic and Transcendentalist movements'], places: ['Persia', 'India', 'Spain'], frameworks: ['Comparative Religion', 'Cultural Diffusion'] },
  '151': { slug: 'sociology-social-structure', name: 'Sociology & Social Structure', label: 'Idea', era: 'Modern', summary: 'The systematic study of society, social institutions, and social relationships. Founded by Auguste Comte and developed by Durkheim, Weber, and Marx, sociology examines how social structures — class, race, gender, religion — shape individual behavior and collective outcomes.', causes: ['Industrial Revolution creating new social classes', 'Enlightenment emphasis on empirical study of society'], effects: ['Informed social policy and welfare state design', 'Provided analytical tools for understanding inequality'], places: ['France', 'Germany', 'United States'], frameworks: ['Cause & Effect', 'Economic Systems'] },
  '152': { slug: 'anthropology-ethnography', name: 'Anthropology & Ethnography', label: 'Idea', era: 'Modern', summary: 'The study of human societies and cultures through direct observation and participation. From Malinowski\'s fieldwork in the Trobriand Islands to Lévi-Strauss\'s structural anthropology, the discipline has documented human cultural diversity and challenged ethnocentric assumptions about civilization.', causes: ['Colonial encounters with diverse cultures', 'Darwinian framework raising questions about human variation'], effects: ['Challenged racial hierarchies and eurocentrism', 'Preserved knowledge of endangered cultures and languages'], places: ['Papua New Guinea', 'Brazil', 'France'], frameworks: ['Cultural Diffusion', 'Comparative Religion'] },
  '154': { slug: 'psychology-human-behavior', name: 'Psychology & Human Behavior', label: 'Idea', era: 'Modern', summary: 'The scientific study of mind and behavior, from Wundt\'s experimental psychology through Freudian psychoanalysis to cognitive neuroscience. Psychology has transformed understanding of perception, memory, motivation, mental illness, and social interaction across all human cultures.', causes: ['Philosophical debates on mind-body problem', 'Development of experimental methods for studying behavior'], effects: ['Transformed treatment of mental illness', 'Influenced education, marketing, law, and public policy'], places: ['Germany', 'Austria', 'United States'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '161': { slug: 'conservation-preservation-idea', name: 'Conservation & Preservation', label: 'Idea', era: 'Modern', summary: 'The philosophy and practice of protecting natural environments, wildlife, and natural resources from depletion or destruction. From John Muir\'s wilderness preservation to the modern conservation biology framework, this movement has established national parks, wildlife refuges, and environmental regulations worldwide.', causes: ['Rapid deforestation and species extinction from industrialization', 'Romantic movement\'s valorization of nature'], effects: ['Establishment of national park systems worldwide', 'Creation of endangered species legislation'], places: ['United States', 'Kenya', 'Brazil'], frameworks: ['Environmental History', 'Cause & Effect'] },
  '163': { slug: 'sustainability-resource-mgmt', name: 'Sustainability & Resource Management', label: 'Idea', era: 'Contemporary', summary: 'The concept that human development should meet present needs without compromising future generations\' ability to meet theirs. Codified in the 1987 Brundtland Report, sustainability integrates environmental protection, economic development, and social equity into a unified framework for planetary stewardship.', causes: ['Club of Rome\'s Limits to Growth report (1972)', 'Accelerating environmental degradation and resource depletion'], effects: ['UN Sustainable Development Goals adopted by 193 nations', 'Transformed corporate responsibility and policy frameworks'], places: ['Norway', 'Brazil', 'Global'], frameworks: ['Environmental History', 'Economic Systems'] },
  '171': { slug: 'classical-renaissance-aesthetics', name: 'Classical & Renaissance Aesthetics', label: 'Idea', era: 'Classical', summary: 'Artistic and philosophical principles emphasizing harmony, proportion, idealized beauty, and the imitation of nature. From Greek theories of kalos kagathos to Renaissance perspective and humanism, these aesthetic principles shaped Western art, architecture, and literature for two millennia.', causes: ['Greek philosophical inquiry into beauty and form', 'Rediscovery of classical texts during the Renaissance'], effects: ['Established enduring canons of Western art and architecture', 'Influenced global aesthetic traditions through colonialism'], places: ['Athens', 'Florence', 'Rome'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '173': { slug: 'postmodernism-deconstruction', name: 'Postmodernism & Deconstruction', label: 'Idea', era: 'Contemporary', summary: 'Intellectual movements questioning grand narratives, objective truth, and fixed meaning. Derrida\'s deconstruction, Foucault\'s power-knowledge analysis, and Lyotard\'s incredulity toward metanarratives challenged Enlightenment certainties and transformed literary criticism, architecture, philosophy, and social theory.', causes: ['Disillusionment with modernist grand narratives after World War II', 'Structuralist linguistics questioning stable meaning'], effects: ['Transformed humanities and social sciences methodology', 'Influenced contemporary art, architecture, and culture'], places: ['France', 'United States', 'Germany'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },

  // Class 2 — People
  '201': { slug: 'confucius-educator', name: 'Confucius', label: 'Person', era: 'Classical', summary: 'Chinese philosopher and educator (551-479 BCE) whose teachings on ethics, social relationships, and governance became the foundation of East Asian civilizational values. As history\'s most influential educator, Confucius established a tradition of learning that shaped Chinese imperial examinations, Korean yangban culture, and Japanese Confucian schools for over two millennia.', causes: ['Spring and Autumn period social disorder in China', 'Decline of Zhou dynasty moral authority'], effects: ['Confucian civil service examinations shaped Chinese governance', 'Influenced moral philosophy across East Asia'], places: ['China', 'Korea', 'Japan'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '202': { slug: 'mayer-amschel-rothschild', name: 'Mayer Amschel Rothschild', label: 'Person', era: 'Early Modern', summary: 'German-Jewish banker (1744-1812) who founded the Rothschild banking dynasty, establishing an international financial network that financed governments, wars, and infrastructure across Europe. His five sons created branches in Frankfurt, London, Paris, Vienna, and Naples, making the Rothschilds the most powerful banking family of the 19th century.', causes: ['European demand for cross-border financial services', 'Napoleonic Wars creating enormous government financing needs'], effects: ['Pioneered international banking and bond markets', 'Financed railways, canals, and industrial development'], places: ['Frankfurt', 'London', 'Paris'], frameworks: ['Economic Systems', 'Cause & Effect'] },
  '203': { slug: 'jesse-owens-athlete', name: 'Jesse Owens', label: 'Person', era: 'Modern', summary: 'American track and field athlete (1913-1980) who won four gold medals at the 1936 Berlin Olympics, defying Nazi racial ideology. His victories in the 100m, 200m, long jump, and 4x100m relay before Adolf Hitler and 110,000 spectators became one of the most powerful symbolic moments in sports history.', causes: ['African American athletic talent despite segregation', 'Nazi Germany hosting Olympics as propaganda showcase'], effects: ['Challenged Nazi master race ideology on world stage', 'Became symbol of athletic excellence transcending racism'], places: ['Berlin', 'United States', 'Alabama'], frameworks: ['Cause & Effect', 'Cultural Diffusion'] },
  '204': { slug: 'gustave-eiffel-engineer', name: 'Gustave Eiffel', label: 'Person', era: 'Modern', summary: 'French civil engineer (1832-1923) who designed the iconic Eiffel Tower for the 1889 Paris Exposition, as well as the internal framework of the Statue of Liberty. His pioneering work in metal construction, wind resistance calculations, and aerodynamics advanced structural engineering and made him a symbol of industrial-age innovation.', causes: ['French desire to celebrate centennial of the Revolution', 'Advances in iron and steel construction techniques'], effects: ['Eiffel Tower became symbol of modern engineering', 'Advanced understanding of aerodynamics and wind forces'], places: ['Paris', 'New York', 'France'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '205': { slug: 'herodotus-chronicler', name: 'Herodotus', label: 'Person', era: 'Classical', summary: 'Greek historian (c. 484-425 BCE) known as the "Father of History" for his Histories, the first systematic investigation of past events. His account of the Greco-Persian Wars combined eyewitness research, cultural ethnography, and narrative storytelling, establishing the Western tradition of historical inquiry.', causes: ['Greek victory in Persian Wars demanding explanation', 'Ionian intellectual tradition of rational inquiry'], effects: ['Established history as a discipline of inquiry', 'Preserved knowledge of ancient Near Eastern cultures'], places: ['Halicarnassus', 'Athens', 'Egypt'], frameworks: ['Cause & Effect', 'Cultural Diffusion'] },
  '211': { slug: 'euclid-mathematician', name: 'Euclid', label: 'Person', era: 'Classical', summary: 'Greek mathematician (c. 300 BCE) whose Elements remained the standard textbook for geometry for over 2,000 years. Working in Alexandria, Euclid systematized existing mathematical knowledge into a deductive framework of definitions, axioms, and proofs that became the model for logical reasoning in Western science.', causes: ['Accumulated Greek mathematical knowledge requiring systematization', 'Patronage of the Ptolemaic court in Alexandria'], effects: ['Elements used as primary math textbook for 2,000+ years', 'Established axiomatic-deductive method foundational to science'], places: ['Alexandria', 'Greece'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '212': { slug: 'immanuel-kant-ethicist', name: 'Immanuel Kant', label: 'Person', era: 'Early Modern', summary: 'German philosopher (1724-1804) whose Critique of Pure Reason and Groundwork of the Metaphysics of Morals transformed Western philosophy. His categorical imperative — act only according to maxims you could will as universal laws — became the foundation of modern deontological ethics and profoundly influenced legal and political theory.', causes: ['Hume\'s empiricist challenge to rationalism', 'Enlightenment demand for rational foundations of morality'], effects: ['Reshaped epistemology, ethics, and aesthetics', 'Influenced human rights theory and international law'], places: ['Konigsberg', 'Germany'], frameworks: ['Cause & Effect', 'Political Systems'] },
  '223': { slug: 'sitting-bull-indigenous-leader', name: 'Sitting Bull', label: 'Person', era: 'Modern', summary: 'Hunkpapa Lakota leader (c. 1831-1890) who united Sioux tribes against U.S. government encroachment. His spiritual leadership at the Battle of the Little Bighorn (1876) — where combined Native forces defeated Custer\'s 7th Cavalry — made him an enduring symbol of indigenous resistance to colonial expansion in North America.', causes: ['U.S. westward expansion threatening Lakota territories', 'Violation of Fort Laramie Treaty after Black Hills gold discovery'], effects: ['Became symbol of Native American resistance', 'Intensified U.S. military campaigns against Plains peoples'], places: ['South Dakota', 'Montana', 'United States'], frameworks: ['Empire & Colonialism', 'Cause & Effect'] },
  '231': { slug: 'hugo-grotius-jurist', name: 'Hugo Grotius', label: 'Person', era: 'Early Modern', summary: 'Dutch jurist (1583-1645) known as the "Father of International Law" for his groundbreaking work De Jure Belli ac Pacis (On the Law of War and Peace, 1625). Grotius argued that natural law bound nations even in war, establishing principles of sovereignty, freedom of the seas, and just war theory that underpin modern international law.', causes: ['Thirty Years\' War creating need for rules of warfare', 'Dutch maritime disputes requiring legal frameworks'], effects: ['Foundation of modern international law', 'Influenced Treaty of Westphalia and sovereignty concepts'], places: ['Netherlands', 'France', 'Sweden'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '241': { slug: 'hippocrates-physician', name: 'Hippocrates', label: 'Person', era: 'Classical', summary: 'Greek physician (c. 460-370 BCE) known as the "Father of Medicine" for separating medical practice from religious superstition. The Hippocratic Corpus established clinical observation, prognosis, and ethical practice as foundations of medicine, while the Hippocratic Oath remains a touchstone of medical ethics today.', causes: ['Greek rationalist tradition applied to healing', 'Need to distinguish empirical medicine from temple healing'], effects: ['Established medicine as rational, observation-based discipline', 'Hippocratic Oath remains foundation of medical ethics'], places: ['Kos', 'Athens', 'Greece'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '242': { slug: 'nicolaus-copernicus-astronomer', name: 'Nicolaus Copernicus', label: 'Person', era: 'Early Modern', summary: 'Polish astronomer (1473-1543) who formulated the heliocentric model of the solar system, placing the Sun rather than Earth at the center. His De Revolutionibus Orbium Coelestium (1543) launched the Scientific Revolution by challenging the Ptolemaic geocentric model that had dominated astronomy for 1,400 years.', causes: ['Accumulated discrepancies in Ptolemaic astronomical tables', 'Renaissance recovery of ancient Greek heliocentric ideas'], effects: ['Launched the Copernican Revolution in science', 'Challenged Church authority on cosmological questions'], places: ['Poland', 'Italy', 'Germany'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '243': { slug: 'charles-darwin-naturalist', name: 'Charles Darwin', label: 'Person', era: 'Modern', summary: 'English naturalist (1809-1882) whose On the Origin of Species (1859) presented the theory of evolution by natural selection, fundamentally transforming biology and humanity\'s understanding of its place in nature. His five-year voyage on HMS Beagle and decades of meticulous research produced one of science\'s most consequential theories.', causes: ['Observations during Beagle voyage of species variation', 'Malthus\'s population theory suggesting competition for resources'], effects: ['Unified biology under evolutionary framework', 'Transformed understanding of human origins and diversity'], places: ['England', 'Galapagos Islands', 'Australia'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '252': { slug: 'thomas-aquinas-theologian', name: 'Thomas Aquinas', label: 'Person', era: 'Medieval', summary: 'Italian Dominican friar and theologian (1225-1274) whose Summa Theologica synthesized Aristotelian philosophy with Christian theology, creating the most comprehensive philosophical-theological system of the medieval period. His natural law theory, five proofs for God\'s existence, and just war doctrine continue to influence Catholic teaching and Western philosophy.', causes: ['Recovery of Aristotelian texts via Arabic translations', 'Need to reconcile faith and reason in medieval universities'], effects: ['Summa Theologica became foundation of Catholic theology', 'Natural law theory influenced Western legal traditions'], places: ['Italy', 'Paris', 'Cologne'], frameworks: ['Doctrine Development', 'Cause & Effect'] },
  '261': { slug: 'leo-tolstoy-author', name: 'Leo Tolstoy', label: 'Person', era: 'Modern', summary: 'Russian novelist (1828-1910) whose War and Peace and Anna Karenina are considered among the greatest works of world literature. Beyond fiction, Tolstoy\'s philosophical writings on nonviolent resistance, Christian anarchism, and the meaning of life influenced Gandhi, Martin Luther King Jr., and countless social reformers.', causes: ['Russian literary tradition building toward realism', 'Personal spiritual crisis driving philosophical inquiry'], effects: ['Set standard for the modern novel worldwide', 'Nonviolent philosophy influenced Gandhi and King'], places: ['Russia', 'Moscow', 'Yasnaya Polyana'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '262': { slug: 'rumi-poet', name: 'Rumi', label: 'Person', era: 'Medieval', summary: 'Persian poet and Sufi mystic (1207-1273) whose Masnavi and Divan-e Shams-e Tabrizi are masterworks of world poetry. Born in Balkh (modern Afghanistan), Rumi settled in Konya where his ecstatic poetry on divine love, spiritual longing, and human unity transcended cultural boundaries, making him the best-selling poet in the United States 800 years after his death.', causes: ['Persian literary tradition of mystical poetry', 'Transformative friendship with wandering dervish Shams-e Tabrizi'], effects: ['Founded the Mevlevi (Whirling Dervish) order', 'Became most widely read poet in the Western world'], places: ['Afghanistan', 'Turkey', 'Iran'], frameworks: ['Comparative Religion', 'Cultural Diffusion'] },
  '263': { slug: 'johann-sebastian-bach-composer', name: 'Johann Sebastian Bach', label: 'Person', era: 'Early Modern', summary: 'German composer (1685-1750) whose mastery of counterpoint, harmony, and musical form produced works — the Brandenburg Concertos, Well-Tempered Clavier, Mass in B Minor — that represent the pinnacle of Baroque music and remain foundational to Western musical tradition.', causes: ['German Lutheran musical tradition emphasizing congregational music', 'Baroque era\'s technical and aesthetic developments'], effects: ['Established standards of Western musical composition', 'Influenced virtually every subsequent Western composer'], places: ['Germany', 'Leipzig', 'Weimar'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '264': { slug: 'michelangelo-painter-sculptor', name: 'Michelangelo', label: 'Person', era: 'Early Modern', summary: 'Italian Renaissance artist (1475-1564) whose Sistine Chapel ceiling, David, and Pieta represent the highest achievements of Western visual art. As painter, sculptor, architect, and poet, Michelangelo embodied the Renaissance ideal of the universal genius and transformed the role of the artist from craftsman to creative visionary.', causes: ['Papal and Medici patronage of the arts', 'Renaissance humanist emphasis on individual genius'], effects: ['Redefined possibilities of painting and sculpture', 'Sistine Chapel became symbol of Western artistic achievement'], places: ['Florence', 'Rome', 'Italy'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '265': { slug: 'frank-lloyd-wright-architect', name: 'Frank Lloyd Wright', label: 'Person', era: 'Modern', summary: 'American architect (1867-1959) who designed over 1,000 structures including Fallingwater, the Guggenheim Museum, and Taliesin. His organic architecture philosophy — that buildings should harmonize with their environment — and Prairie Style innovations made him the most influential American architect of the 20th century.', causes: ['Arts and Crafts movement rejecting industrial uniformity', 'American landscape inspiring new architectural forms'], effects: ['Organic architecture influenced global design', 'Pioneered open floor plans now standard in residential design'], places: ['United States', 'Chicago', 'New York'], frameworks: ['Innovation & Technology', 'Cultural Diffusion'] },
  '271': { slug: 'harriet-tubman-abolitionist', name: 'Harriet Tubman', label: 'Person', era: 'Modern', summary: 'American abolitionist (c. 1822-1913) who escaped slavery and subsequently made roughly 13 missions to rescue approximately 70 enslaved people via the Underground Railroad. During the Civil War she served as a scout, spy, and the first woman to lead an armed expedition (the Combahee River Raid), freeing more than 700 enslaved people.', causes: ['Personal experience of slavery\'s brutality', 'Network of abolitionists operating the Underground Railroad'], effects: ['Became icon of resistance to slavery', 'Advanced the cause of abolition through direct action'], places: ['Maryland', 'Philadelphia', 'United States'], frameworks: ['Cause & Effect', 'Political Systems'] },
  '272': { slug: 'emmeline-pankhurst-suffragist', name: 'Emmeline Pankhurst', label: 'Person', era: 'Modern', summary: 'British political activist (1858-1928) who led the suffragette movement as founder of the Women\'s Social and Political Union. Her militant tactics — hunger strikes, property destruction, mass demonstrations — generated enormous controversy but ultimately contributed to British women gaining the vote in 1918.', causes: ['Decades of peaceful suffrage advocacy producing no results', 'Growing women\'s education and professional participation'], effects: ['British women gained partial suffrage in 1918, full in 1928', 'Inspired women\'s suffrage movements worldwide'], places: ['Manchester', 'London', 'England'], frameworks: ['Cause & Effect', 'Political Systems'] },
  '273': { slug: 'cesar-chavez-labor-organizer', name: 'César Chávez', label: 'Person', era: 'Contemporary', summary: 'American labor leader (1927-1993) who co-founded the National Farm Workers Association (later United Farm Workers) and organized migrant agricultural workers in California. His nonviolent tactics — boycotts, fasts, marches — improved wages and working conditions for farmworkers and made him a hero of the American labor and Latino civil rights movements.', causes: ['Exploitation of migrant farmworkers in California agriculture', 'Inspired by Gandhi\'s nonviolent resistance methods'], effects: ['Won collective bargaining rights for farmworkers', 'Became symbol of Latino civil rights movement'], places: ['California', 'United States', 'Arizona'], frameworks: ['Cause & Effect', 'Economic Systems'] },
  '291': { slug: 'yuri-gagarin-cosmonaut', name: 'Yuri Gagarin', label: 'Person', era: 'Contemporary', summary: 'Soviet cosmonaut (1934-1968) who became the first human in space on April 12, 1961, orbiting Earth in Vostok 1 in 108 minutes. His flight represented the pinnacle of the Soviet space program and a defining moment of the Space Race, demonstrating that humans could survive in space and inspiring generations of space exploration.', causes: ['Cold War competition driving Soviet and American space programs', 'Soviet rocketry advances under Sergei Korolev'], effects: ['Accelerated U.S. commitment to Moon landing', 'Became global symbol of human spaceflight achievement'], places: ['Russia', 'Kazakhstan', 'Soviet Union'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '292': { slug: 'jacques-cousteau-explorer', name: 'Jacques Cousteau', label: 'Person', era: 'Contemporary', summary: 'French naval officer, explorer, and filmmaker (1910-1997) who co-developed the Aqua-Lung (modern scuba) and pioneered underwater exploration. His ship Calypso and television series The Undersea World of Jacques Cousteau brought ocean science to millions and catalyzed the marine conservation movement.', causes: ['Desire to explore the ocean without heavy diving suits', 'Development of self-contained underwater breathing apparatus'], effects: ['Popularized marine science and ocean exploration', 'Catalyzed global marine conservation movement'], places: ['France', 'Mediterranean', 'Global oceans'], frameworks: ['Environmental History', 'Innovation & Technology'] },
  '293': { slug: 'gerardus-mercator-cartographer', name: 'Gerardus Mercator', label: 'Person', era: 'Early Modern', summary: 'Flemish cartographer (1512-1594) who created the Mercator projection (1569), a cylindrical map projection that represents lines of constant course as straight lines — essential for maritime navigation. His world maps and atlases (a term he popularized) defined modern cartography and remained standard for navigation for over 400 years.', causes: ['Age of Exploration demanding accurate nautical charts', 'Mathematical advances enabling projection calculations'], effects: ['Mercator projection became standard for navigation charts', 'Shaped global geographic imagination for centuries'], places: ['Flanders', 'Germany', 'Netherlands'], frameworks: ['Innovation & Technology', 'Cultural Diffusion'] },

  // Class 3 — Institutions
  '315': { slug: 'haudenosaunee-great-law-of-peace', name: 'Haudenosaunee Great Law of Peace', label: 'Institution', era: 'Medieval', summary: 'The constitution of the Iroquois Confederacy (Haudenosaunee), possibly codified as early as 1142 CE, establishing a representative council of 50 sachems, consensus decision-making, and women\'s political power (clan mothers nominated chiefs). The Great Law of Peace — one of the oldest participatory governance systems — influenced American constitutional framers, particularly Benjamin Franklin.', causes: ['Inter-tribal warfare among Iroquoian peoples demanding a peace framework', 'Peacemaker and Hiawatha\'s diplomacy uniting five nations'], effects: ['Influenced American constitutional framers (particularly Franklin)', 'Maintained regional peace and power for centuries'], places: ['New York', 'United States', 'Canada'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '320': { slug: 'roman-legal-system', name: 'Roman Legal System', label: 'Institution', era: 'Classical', summary: 'The comprehensive system of laws, courts, and jurisprudence developed by the Roman Republic and Empire from the Twelve Tables (450 BCE) to Justinian\'s Corpus Juris Civilis (534 CE). Roman law introduced concepts of legal personality, contract, property, and due process that form the foundation of civil law systems used by over half the world\'s population today.', causes: ['Plebeian demands for written, accessible laws', 'Administrative needs of expanding Roman state'], effects: ['Foundation of civil law systems in continental Europe, Latin America, and Asia', 'Concepts of legal personality and due process entered Western legal tradition'], places: ['Rome', 'Constantinople', 'Italy'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '322': { slug: 'inns-of-court-london', name: 'Inns of Court', label: 'Institution', era: 'Medieval', summary: 'The four professional associations of barristers in England — Lincoln\'s Inn, Gray\'s Inn, Inner Temple, and Middle Temple — established in the 14th century as the exclusive institutions for training and regulating lawyers. The Inns created the common law legal profession, requiring years of apprenticeship, dining rituals, and moot court practice that shaped Anglo-American legal education.', causes: ['Growing complexity of English common law requiring specialized training', 'Royal courts needing trained advocates for legal proceedings'], effects: ['Created the professional barrister class in England', 'Model influenced law schools in America and Commonwealth'], places: ['London', 'England'], frameworks: ['Institutional Analysis', 'Cause & Effect'] },
  '323': { slug: 'interstate-commerce-commission', name: 'Interstate Commerce Commission', label: 'Institution', era: 'Modern', summary: 'The first independent regulatory agency in the United States (1887-1995), created to regulate railroad rates and prevent monopolistic practices. The ICC established the model for independent regulatory commissions — combining quasi-legislative, quasi-executive, and quasi-judicial functions — that would be replicated across American government and worldwide.', causes: ['Railroad monopolies exploiting farmers and small businesses', 'Populist movement demanding government regulation of industry'], effects: ['Established model for independent regulatory agencies worldwide', 'Set precedent for government regulation of private industry'], places: ['Washington D.C.', 'United States'], frameworks: ['Economic Systems', 'Political Systems'] },
  '345': { slug: 'al-azhar-university-seminary', name: 'Al-Azhar University', label: 'Institution', era: 'Medieval', summary: 'Founded in 970 CE in Cairo as a center of Islamic learning, Al-Azhar is one of the world\'s oldest continuously operating universities and the foremost institution of Sunni Islamic scholarship. For over a millennium it has trained scholars, issued fatwas, and served as the authoritative voice on Islamic jurisprudence and theology.', causes: ['Fatimid dynasty\'s promotion of Ismaili scholarship', 'Need for centralized Islamic legal and theological authority'], effects: ['Became the most authoritative institution in Sunni Islam', 'Trained Islamic scholars across the Muslim world for a millennium'], places: ['Cairo', 'Egypt'], frameworks: ['Doctrine Development', 'Institutional Analysis'] },
  '352': { slug: 'bell-labs-research', name: 'Bell Laboratories', label: 'Institution', era: 'Contemporary', summary: 'American industrial research laboratory (est. 1925) that produced some of the 20th century\'s most consequential inventions: the transistor, laser, Unix operating system, C programming language, and information theory. Bell Labs researchers have received 9 Nobel Prizes, making it the most productive corporate research institution in history.', causes: ['AT&T monopoly generating massive R&D investment', 'Culture of fundamental research alongside applied innovation'], effects: ['Transistor launched the electronics revolution', 'Information theory and Unix transformed computing'], places: ['Murray Hill', 'New Jersey', 'United States'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '353': { slug: 'greenwich-observatory', name: 'Royal Observatory Greenwich', label: 'Institution', era: 'Early Modern', summary: 'Founded in 1675 by Charles II to solve the problem of determining longitude at sea. Greenwich Observatory\'s precise astronomical observations, development of marine chronometers, and establishment of the Prime Meridian (0 degrees longitude) made it the reference point for global timekeeping and navigation.', causes: ['Maritime disasters caused by inability to determine longitude', 'Royal interest in improving naval navigation'], effects: ['Established Prime Meridian and Greenwich Mean Time standards', 'Enabled accurate oceanic navigation worldwide'], places: ['Greenwich', 'London', 'England'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '354': { slug: 'johns-hopkins-hospital', name: 'Johns Hopkins Hospital', label: 'Institution', era: 'Modern', summary: 'American teaching hospital (est. 1889) that revolutionized medical education and practice by combining research, teaching, and clinical care. Under William Osler, William Halsted, and others, Johns Hopkins introduced bedside teaching, residency training, and evidence-based medicine that became the global standard for academic medicine.', causes: ['Philanthropy of Johns Hopkins providing unprecedented endowment', 'German university model of combining research and teaching'], effects: ['Transformed American medical education and practice', 'Residency training model adopted worldwide'], places: ['Baltimore', 'Maryland', 'United States'], frameworks: ['Innovation & Technology', 'Institutional Analysis'] },
  '363': { slug: 'globe-theatre-london', name: 'Globe Theatre', label: 'Institution', era: 'Early Modern', summary: 'Elizabethan playhouse (built 1599) in Southwark, London, associated with William Shakespeare and the Lord Chamberlain\'s Men. The open-air amphitheater\'s design — standing pit, tiered galleries, thrust stage — created an intimate performance space where Shakespeare\'s plays reached audiences from groundlings to royalty, defining English dramatic tradition.', causes: ['Flourishing of English drama during Elizabethan era', 'Commercial theater model replacing aristocratic patronage'], effects: ['Hosted premieres of Shakespeare\'s greatest plays', 'Established English theatrical tradition still influential today'], places: ['London', 'England'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '380': { slug: 'education-institutions-overview', name: 'Educational Institutions', label: 'Institution', era: 'Classical', summary: 'Organized centers for transmitting knowledge, skills, and cultural values across generations. From Plato\'s Academy and Imperial Chinese academies to medieval universities and modern public school systems, educational institutions have served as both preservers of tradition and engines of social transformation across all civilizations.', causes: ['Need to train administrators for complex states', 'Religious institutions establishing scriptural education'], effects: ['Created literate administrative classes across civilizations', 'Enabled scientific and cultural knowledge transmission'], places: ['Athens', 'Baghdad', 'Paris'], frameworks: ['Institutional Analysis', 'Cultural Diffusion'] },
  '383': { slug: 'al-qarawiyyin-madrasa', name: 'University of al-Qarawiyyin', label: 'Institution', era: 'Medieval', summary: 'Founded in 859 CE in Fez, Morocco, by Fatima al-Fihri, al-Qarawiyyin is recognized by UNESCO and Guinness as the oldest existing, continually operating educational institution in the world. It pioneered the concept of a degree-granting university and trained scholars in Islamic jurisprudence, grammar, astronomy, and mathematics for over a millennium.', causes: ['Fatima al-Fihri\'s endowment from inherited wealth', 'Growing demand for Islamic scholarship in Maghreb region'], effects: ['Model for degree-granting educational institutions', 'Trained scholars who spread knowledge across Islamic world'], places: ['Fez', 'Morocco'], frameworks: ['Institutional Analysis', 'Cultural Diffusion'] },
  '384': { slug: 'prussian-education-system', name: 'Prussian Education System', label: 'Institution', era: 'Modern', summary: 'The first modern compulsory public education system, established by Prussia in the early 19th century under Wilhelm von Humboldt. Featuring age-graded classrooms, trained professional teachers, standardized curricula, and state funding, the Prussian model was adopted by virtually every nation and remains the template for public education worldwide.', causes: ['Prussian defeat by Napoleon demanding national reform', 'Enlightenment philosophy emphasizing universal education'], effects: ['Model adopted by public education systems worldwide', 'Created universal literacy as standard national goal'], places: ['Prussia', 'Germany', 'Berlin'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '392': { slug: 'british-royal-navy', name: 'Royal Navy', label: 'Institution', era: 'Early Modern', summary: 'Britain\'s naval force that dominated global seas from the defeat of the Spanish Armada (1588) through World War II. The Royal Navy protected British trade routes, enforced colonial rule, suppressed the transatlantic slave trade after 1807, and served as the model for modern professional navies worldwide.', causes: ['England\'s island geography requiring strong naval defense', 'Competition with Spain and France for colonial trade'], effects: ['Enabled the British Empire\'s global dominance', 'Suppressed Atlantic slave trade in 19th century'], places: ['England', 'Gibraltar', 'Global oceans'], frameworks: ['Empire & Colonialism', 'Cause & Effect'] },
  '393': { slug: 'mi6-secret-intelligence', name: 'Secret Intelligence Service (MI6)', label: 'Institution', era: 'Modern', summary: 'Britain\'s foreign intelligence agency, established in 1909 as the Secret Service Bureau. MI6 played critical roles in both World Wars, the Cold War, and counter-terrorism operations. Its organizational model — combining human intelligence (HUMINT), signals intelligence, and diplomatic cover operations — influenced intelligence agencies worldwide.', causes: ['Pre-World War I espionage threats from Germany', 'Need for coordinated foreign intelligence gathering'], effects: ['Influenced intelligence agency models worldwide', 'Critical role in WWII code-breaking and Cold War operations'], places: ['London', 'England', 'Global'], frameworks: ['Political Systems', 'Cause & Effect'] },

  // Class 4 — Places
  '420': { slug: 'sahel-region', name: 'Sahel Region', label: 'Place', era: 'Prehistoric', summary: 'The semi-arid transitional zone stretching 5,400 km across Africa from the Atlantic to the Red Sea, between the Sahara Desert and the tropical savannas. The Sahel has been a crucible of human history: birthplace of ancient kingdoms (Ghana, Mali, Songhai), corridor for trans-Saharan trade, and frontline of contemporary climate change and desertification.', causes: ['Climatic zone between Sahara and tropical Africa', 'Available grazing land attracting pastoral peoples'], effects: ['Corridor for trans-Saharan gold and salt trade', 'Birthplace of West African empires and Islamic scholarship'], places: ['Mali', 'Niger', 'Chad'], frameworks: ['Environmental History', 'Economic Systems'] },
  '421': { slug: 'great-rift-valley-region', name: 'Great Rift Valley', label: 'Place', era: 'Prehistoric', summary: 'A geological trench system stretching 6,000 km from Lebanon to Mozambique, containing some of humanity\'s most important archaeological sites. The East African Rift — with sites like Olduvai Gorge, Laetoli, and Hadar — has yielded the oldest hominin fossils, making it the "Cradle of Humankind" and the most significant region for understanding human origins.', causes: ['Tectonic plate divergence creating unique geological formations', 'Diverse ecosystems supporting early hominin evolution'], effects: ['Yielded oldest known hominin fossils and tools', 'UNESCO World Heritage sites preserving human evolutionary record'], places: ['Tanzania', 'Kenya', 'Ethiopia'], frameworks: ['Environmental History', 'Innovation & Technology'] },
  '424': { slug: 'yellow-river-region', name: 'Yellow River (Huang He) Basin', label: 'Place', era: 'Prehistoric', summary: 'The basin of China\'s second-longest river, called "the Cradle of Chinese Civilization." The fertile loess plains of the Yellow River supported the earliest Chinese agricultural settlements, Shang dynasty capitals, and the development of Chinese writing, bronze technology, and political philosophy that would shape East Asian civilization for millennia.', causes: ['Fertile loess soil deposits enabling agriculture', 'Reliable water source in temperate climate zone'], effects: ['Birthplace of Chinese civilization and writing', 'Catastrophic floods shaped Chinese governance and engineering'], places: ['China', 'Henan', 'Shaanxi'], frameworks: ['Environmental History', 'Cause & Effect'] },
  '425': { slug: 'mediterranean-basin-region', name: 'Mediterranean Basin', label: 'Place', era: 'Classical', summary: 'The lands surrounding the Mediterranean Sea — from Iberia to the Levant, from North Africa to southern Europe — that constituted the geopolitical center of the ancient and medieval world. The Mediterranean enabled trade, colonization, and cultural exchange among Phoenician, Greek, Roman, Byzantine, and Islamic civilizations, making it history\'s most consequential maritime corridor.', causes: ['Enclosed sea enabling reliable maritime navigation', 'Diverse climates and resources encouraging trade networks'], effects: ['Facilitated rise of Western civilization\'s foundational cultures', 'Maritime trade patterns that persisted for 3,000+ years'], places: ['Italy', 'Greece', 'Egypt'], frameworks: ['Cultural Diffusion', 'Economic Systems'] },
  '426': { slug: 'mesoamerica-region', name: 'Mesoamerica', label: 'Place', era: 'Classical', summary: 'The cultural region extending from central Mexico through Belize, Guatemala, El Salvador, Honduras, Nicaragua, and Costa Rica, where the Olmec, Maya, Zapotec, Teotihuacan, and Aztec civilizations independently developed agriculture, writing, astronomy, monumental architecture, and complex states without contact with Eurasia.', causes: ['Independent development of maize agriculture', 'Geographic isolation enabling unique cultural evolution'], effects: ['Independent invention of writing, mathematics, and astronomy', 'Created some of the ancient world\'s largest cities'], places: ['Mexico', 'Guatemala', 'Honduras'], frameworks: ['Cultural Diffusion', 'Innovation & Technology'] },
  '427': { slug: 'polynesian-triangle-region', name: 'Polynesian Triangle', label: 'Place', era: 'Medieval', summary: 'The vast oceanic region bounded by Hawaii, New Zealand, and Easter Island — the largest cultural zone on Earth — colonized by Polynesian navigators using celestial navigation, ocean currents, and oral tradition. Polynesian settlement of remote Pacific islands represents the greatest feat of open-ocean navigation in human history.', causes: ['Austronesian expansion from Southeast Asia', 'Development of double-hulled canoe and celestial navigation'], effects: ['Settled the most remote habitable islands on Earth', 'Created distinct cultural traditions across Polynesia'], places: ['Hawaii', 'New Zealand', 'Easter Island'], frameworks: ['Cultural Diffusion', 'Innovation & Technology'] },
  '428': { slug: 'central-asian-steppe-region', name: 'Central Asian Steppe', label: 'Place', era: 'Prehistoric', summary: 'The vast grassland corridor stretching from Hungary to Manchuria that served as a highway for nomadic peoples, enabling the spread of horses, chariots, metallurgy, and empires across Eurasia. Scythians, Huns, Turks, and Mongols used steppe mobility to build empires that repeatedly reshaped sedentary civilizations from China to Europe.', causes: ['Grassland ecology favoring horse-based pastoral nomadism', 'Horse domestication on the Pontic-Caspian steppe'], effects: ['Enabled rapid movement of peoples, languages, and technologies', 'Mongol Empire created largest contiguous land empire in history'], places: ['Mongolia', 'Kazakhstan', 'Ukraine'], frameworks: ['Environmental History', 'Empire & Colonialism'] },
  '442': { slug: 'venice-port-city', name: 'Venice', label: 'Place', era: 'Medieval', summary: 'Italian maritime republic and trading hub built on 118 islands in a lagoon, dominating Mediterranean commerce from the 9th to 16th centuries. Venice\'s unique geography, merchant oligarchy, naval power, and position as gateway between Europe and the East made it one of the wealthiest and most influential cities in history.', causes: ['Lagoon location providing natural defense', 'Strategic position between Byzantine and Western European markets'], effects: ['Dominated Mediterranean trade for centuries', 'Pioneered banking, insurance, and commercial law innovations'], places: ['Italy', 'Mediterranean'], frameworks: ['Economic Systems', 'Cause & Effect'] },
  '444': { slug: 'pompeii-ancient-city', name: 'Pompeii', label: 'Place', era: 'Classical', summary: 'Roman city near Naples buried by the eruption of Mount Vesuvius in 79 CE, preserving an extraordinary snapshot of daily life in the Roman Empire. Excavations beginning in 1748 revealed streets, homes, shops, temples, brothels, and even food — making Pompeii the most important archaeological site for understanding Roman urban life.', causes: ['Prosperous Roman trading city at foot of Vesuvius', 'Catastrophic eruption on August 24, 79 CE'], effects: ['Preserved unparalleled record of Roman daily life', 'Pioneered modern archaeological excavation methods'], places: ['Italy', 'Naples', 'Rome'], frameworks: ['Environmental History', 'Cause & Effect'] },
  '450': { slug: 'empires-dynasties-overview', name: 'Empires & Dynasties', label: 'Place', era: 'Classical', summary: 'Large-scale political entities that have dominated human history, from the Akkadian Empire (c. 2334 BCE) through modern colonial empires. Empires arise through military conquest, diplomatic marriage, economic leverage, or cultural prestige, and their rise and fall patterns — overextension, succession crises, peripheral revolts — recur across civilizations and centuries.', causes: ['Military superiority enabling territorial expansion', 'Economic advantages of controlling trade routes'], effects: ['Spread languages, religions, and technologies across vast regions', 'Imperial collapse often fragmented into successor states'], places: ['Rome', 'Beijing', 'Istanbul'], frameworks: ['Empire & Colonialism', 'Cause & Effect'] },
  '451': { slug: 'akkadian-empire', name: 'Akkadian Empire', label: 'Place', era: 'Classical', summary: 'The first multi-ethnic empire in recorded history (c. 2334-2154 BCE), founded by Sargon of Akkad in Mesopotamia. Stretching from the Mediterranean to the Persian Gulf, the Akkadian Empire unified Sumerian and Semitic peoples under a single administration, establishing imperial governance practices that influenced all subsequent Near Eastern empires.', causes: ['Sargon\'s military innovation and political ambition', 'Fertile Crescent agriculture supporting large populations'], effects: ['Established model for imperial governance in the ancient Near East', 'Spread Akkadian language as lingua franca of Mesopotamia'], places: ['Iraq', 'Syria', 'Mesopotamia'], frameworks: ['Empire & Colonialism', 'Cause & Effect'] },
  '453': { slug: 'mongol-empire-medieval', name: 'Mongol Empire', label: 'Place', era: 'Medieval', summary: 'The largest contiguous land empire in history (1206-1368), founded by Genghis Khan and spanning from Korea to Hungary at its peak. The Mongol Empire — through devastating conquest and administrative innovation — created the Pax Mongolica, enabling unprecedented exchange of goods, ideas, technologies, and diseases across Eurasia.', causes: ['Genghis Khan\'s unification of Mongol tribes', 'Superior cavalry tactics and psychological warfare'], effects: ['Created Pax Mongolica enabling Eurasian trade', 'Facilitated transmission of gunpowder, printing, and plague'], places: ['Mongolia', 'China', 'Persia'], frameworks: ['Empire & Colonialism', 'Cultural Diffusion'] },
  '455': { slug: 'british-empire-colonial', name: 'British Empire', label: 'Place', era: 'Modern', summary: 'The largest empire in world history, at its peak in 1920 controlling roughly 25% of the world\'s land and population. Emerging from maritime competition with Spain and the Netherlands, Britain built a global empire through naval supremacy, trading companies, settler colonialism, and industrial power that reshaped language, law, governance, and culture worldwide.', causes: ['Naval supremacy after defeat of Spanish Armada', 'Industrial Revolution providing economic and military advantage'], effects: ['English became global lingua franca', 'Spread parliamentary governance and common law worldwide'], places: ['India', 'Australia', 'Canada'], frameworks: ['Empire & Colonialism', 'Economic Systems'] },
  '463': { slug: 'scythian-nomadic-civilization', name: 'Scythian Civilization', label: 'Place', era: 'Classical', summary: 'Nomadic warrior-pastoralists who dominated the Eurasian steppe from the 8th to 3rd centuries BCE, ranging from the Black Sea to Siberia. The Scythians\' mastery of mounted archery, elaborate gold artwork (animal style), and trade networks connecting Greece to China made them the most powerful nomadic civilization of the ancient world.', causes: ['Horse domestication and mounted warfare techniques', 'Control of steppe trade routes between East and West'], effects: ['Transmitted technologies and art styles across Eurasia', 'Kurgan burial mounds preserved extraordinary gold artifacts'], places: ['Ukraine', 'Kazakhstan', 'Russia'], frameworks: ['Cultural Diffusion', 'Empire & Colonialism'] },
  '472': { slug: 'varanasi-sacred-landscape', name: 'Varanasi', label: 'Place', era: 'Classical', summary: 'One of the world\'s oldest continuously inhabited cities, Varanasi (Benares/Kashi) sits on the Ganges in northern India and is the holiest city in Hinduism, significant in Buddhism and Jainism. For over 3,000 years, millions of pilgrims have come to bathe in the Ganges, cremate their dead on its ghats, and seek spiritual liberation (moksha) in this "City of Light."', causes: ['Sacred geography at confluence of rivers', 'In Hindu cosmology, death in Varanasi liberates from rebirth cycle'], effects: ['Premier pilgrimage destination for 3,000+ years', 'Center of Sanskrit learning, music, and philosophy'], places: ['India', 'Uttar Pradesh'], frameworks: ['Comparative Religion', 'Cultural Diffusion'] },
  '473': { slug: 'gettysburg-battlefield', name: 'Battle of Gettysburg', label: 'Place', era: 'Modern', summary: 'Site of the bloodiest battle of the American Civil War (July 1-3, 1863) in Pennsylvania, where Union forces repelled Robert E. Lee\'s invasion of the North. With over 50,000 casualties, Gettysburg marked the turning point of the war and became — through Lincoln\'s Gettysburg Address — America\'s most sacred battlefield and a symbol of democratic ideals.', causes: ['Lee\'s strategic decision to invade the North', 'Convergence of Confederate and Union forces at crossroads town'], effects: ['Turned the tide of the American Civil War', 'Lincoln\'s Gettysburg Address redefined American democratic purpose'], places: ['Pennsylvania', 'United States'], frameworks: ['Cause & Effect', 'Political Systems'] },

  // Class 5 — Events
  '542': { slug: 'nuremberg-trials-tribunal', name: 'Nuremberg Trials', label: 'EventWindow', era: 'Contemporary', summary: 'The International Military Tribunal (1945-1946) that prosecuted major Nazi war criminals for crimes against peace, war crimes, and crimes against humanity. The Nuremberg Trials established the precedent that individuals — including heads of state — could be held criminally responsible under international law, founding the modern system of international criminal justice.', causes: ['Unprecedented scale of Nazi atrocities', 'Allied agreement to pursue justice rather than summary execution'], effects: ['Established individual criminal responsibility under international law', 'Foundation for International Criminal Court and tribunal system'], places: ['Nuremberg', 'Germany'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '610': { slug: 'political-movements-overview', name: 'Political Movements', label: 'Movement', era: 'Early Modern', summary: 'Organized collective efforts to achieve political change through mass mobilization, ideology, and sustained action. From the English Parliamentarians and French Revolutionaries to 20th-century independence movements, political movements have been the primary engines of democratic expansion, decolonization, and political transformation worldwide.', causes: ['Grievances against existing political arrangements', 'Enlightenment ideas on natural rights and popular sovereignty'], effects: ['Drove democratic revolutions on every continent', 'Decolonization created over 100 new nation-states'], places: ['France', 'India', 'South Africa'], frameworks: ['Political Systems', 'Cause & Effect'] },
  '625': { slug: 'stonewall-lgbtq-rights', name: 'Stonewall Uprising & LGBTQ+ Rights Movement', label: 'Movement', era: 'Contemporary', summary: 'The modern LGBTQ+ rights movement, catalyzed by the Stonewall uprising in New York City (June 28, 1969) when patrons of the Stonewall Inn resisted a police raid. This event ignited a global movement for decriminalization, anti-discrimination protections, marriage equality, and recognition of gender identity that has transformed legal and social landscapes in dozens of countries.', causes: ['Decades of police harassment and criminalization of homosexuality', 'Broader civil rights movements providing organizational models'], effects: ['Transformed legal status of LGBTQ+ people in dozens of countries', 'Marriage equality achieved in 30+ nations'], places: ['New York City', 'United States', 'Global'], frameworks: ['Cause & Effect', 'Political Systems'] },

  // Class 6 — Movements
  '632': { slug: 'counter-reformation-movement', name: 'Counter-Reformation', label: 'Movement', era: 'Early Modern', summary: 'The Catholic Church\'s internal reform movement (c. 1545-1648) responding to the Protestant Reformation. Centered on the Council of Trent (1545-1563), the Counter-Reformation clarified Catholic doctrine, reformed clerical abuses, established seminaries for training priests, and launched global missionary campaigns through the Jesuit order.', causes: ['Protestant Reformation challenging Catholic authority', 'Internal pressures for reform of clerical corruption'], effects: ['Clarified Catholic doctrine through Council of Trent', 'Jesuit missions spread Catholicism to Asia, Americas, and Africa'], places: ['Rome', 'Spain', 'Global'], frameworks: ['Doctrine Development', 'Cause & Effect'] },
  '633': { slug: 'islamic-reform-revival', name: 'Islamic Reform & Revival Movements', label: 'Movement', era: 'Modern', summary: 'A spectrum of movements seeking to revitalize and reform Islam in response to modernization and Western colonialism. From Muhammad ibn Abd al-Wahhab\'s revivalism to Muhammad Abduh\'s modernism and the Deobandi movement, these reformers debated how Islam should engage with modernity, producing both conservative and progressive responses that continue to shape the Muslim world.', causes: ['Decline of Ottoman and Mughal empires', 'Western colonial domination of Muslim-majority lands'], effects: ['Shaped modern political Islam in diverse directions', 'Influenced governance and law across Muslim-majority nations'], places: ['Saudi Arabia', 'Egypt', 'India'], frameworks: ['Doctrine Development', 'Comparative Religion'] },
  '635': { slug: 'bahai-faith-movement', name: 'Baha\'i Faith', label: 'Movement', era: 'Modern', summary: 'A world religion founded by Baha\'u\'llah (1817-1892) in Persia, teaching the essential unity of all religions and the oneness of humanity. Emerging from the Babi movement in 1863, the Baha\'i Faith emphasizes universal education, gender equality, elimination of prejudice, and world governance, growing to 5+ million adherents in virtually every country.', causes: ['Babi movement in Qajar Persia proclaiming a new prophetic dispensation', 'Baha\'u\'llah\'s exile writings articulating universal principles'], effects: ['Established global religious community in 200+ countries', 'Pioneered interfaith dialogue and universal principles of governance'], places: ['Iran', 'Israel', 'Global'], frameworks: ['Comparative Religion', 'Cultural Diffusion'] },
  '643': { slug: 'romanticism-movement', name: 'Romanticism', label: 'Movement', era: 'Modern', summary: 'A cultural and intellectual movement (c. 1790-1850) emphasizing emotion, imagination, nature, and individual experience over Enlightenment rationalism. Romanticism transformed literature (Wordsworth, Goethe, Hugo), music (Beethoven, Chopin), painting (Delacroix, Turner), and philosophy (Schelling, Hegel), while inspiring nationalist movements and environmental consciousness.', causes: ['Reaction against Enlightenment rationalism and industrialization', 'French Revolution\'s emphasis on individual liberty'], effects: ['Transformed Western art, music, and literature', 'Inspired nationalist movements across Europe'], places: ['Germany', 'England', 'France'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '644': { slug: 'bauhaus-avant-garde', name: 'Bauhaus Movement', label: 'Movement', era: 'Modern', summary: 'A German art school and movement (1919-1933) that unified fine arts, crafts, and technology under the principle that form follows function. Founded by Walter Gropius in Weimar, the Bauhaus trained a generation of designers, architects, and artists whose minimalist aesthetic — clean lines, functional design, industrial materials — defined 20th-century modernism.', causes: ['Post-WWI desire to rebuild society through design', 'Arts and Crafts movement\'s emphasis on unifying art and craft'], effects: ['Defined modernist architecture and industrial design', 'Displaced faculty spread Bauhaus principles globally after Nazi closure'], places: ['Weimar', 'Dessau', 'Germany'], frameworks: ['Cultural Diffusion', 'Innovation & Technology'] },
  '645': { slug: 'language-revival-movements', name: 'Language Revival Movements', label: 'Movement', era: 'Modern', summary: 'Organized efforts to revitalize endangered or dormant languages as expressions of cultural identity and political sovereignty. From the revival of Hebrew as a spoken language in Palestine to Irish Gaelic revival, Catalan normalization, and contemporary efforts to preserve indigenous languages, these movements assert that linguistic diversity is essential to cultural survival.', causes: ['Colonial suppression of indigenous languages', 'Nationalist movements linking language to political identity'], effects: ['Hebrew revived as daily spoken language (unique achievement)', 'UNESCO atlas documents 2,500+ endangered languages worldwide'], places: ['Israel', 'Ireland', 'Wales'], frameworks: ['Cultural Diffusion', 'Political Systems'] },
  '652': { slug: 'vienna-circle-positivism', name: 'Vienna Circle & Logical Positivism', label: 'Movement', era: 'Modern', summary: 'A group of philosophers, mathematicians, and scientists meeting in Vienna (1924-1936) who developed logical positivism — the view that only empirically verifiable statements are meaningful. Led by Moritz Schlick and including Rudolf Carnap and Kurt Gödel, the Vienna Circle\'s emphasis on scientific verification, logical analysis, and the unity of science profoundly shaped 20th-century philosophy.', causes: ['Advances in logic by Frege, Russell, and Wittgenstein', 'Desire to eliminate metaphysical speculation from science'], effects: ['Transformed philosophy of science and analytic philosophy', 'Influence persisted through Popper\'s falsificationism and Quine\'s empiricism'], places: ['Vienna', 'Austria', 'England'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '653': { slug: 'open-science-movement', name: 'Open Science Movement', label: 'Movement', era: 'Contemporary', summary: 'The movement to make scientific research — publications, data, methods, and software — freely accessible to all. From the Budapest Open Access Initiative (2001) to preprint servers, open data mandates, and open-source research tools, the movement challenges traditional academic publishing and aims to accelerate scientific discovery through transparency and collaboration.', causes: ['Internet enabling free distribution of scholarship', 'Rising journal subscription costs restricting access to research'], effects: ['Preprint servers and open access journals transformed publishing', 'Major funders now mandate open access for publicly funded research'], places: ['Budapest', 'United States', 'Global'], frameworks: ['Innovation & Technology', 'Institutional Analysis'] },
  '661': { slug: 'first-industrial-revolution', name: 'First Industrial Revolution', label: 'Movement', era: 'Modern', summary: 'The transition from agrarian handicraft economies to machine manufacturing (c. 1760-1840), originating in Britain. Powered by steam engines, textile mills, iron foundries, and coal mines, the Industrial Revolution transformed economic production, social structure, urbanization, and living standards — arguably the most consequential economic transformation in human history.', causes: ['Agricultural revolution freeing labor from farms', 'British advantages in coal, capital, and stable institutions'], effects: ['Transformed global economic production and living standards', 'Created industrial working class and urban society'], places: ['England', 'Manchester', 'Birmingham'], frameworks: ['Economic Systems', 'Innovation & Technology'] },
  '663': { slug: 'green-technology-movement', name: 'Green Technology Movement', label: 'Movement', era: 'Contemporary', summary: 'The development and deployment of technologies that reduce environmental impact — solar, wind, electric vehicles, green building, carbon capture. Driven by climate science, policy incentives, and falling costs, green technology has grown from a niche concern to a multi-trillion-dollar industry transforming energy, transportation, and construction.', causes: ['Climate change scientific consensus demanding emissions reduction', 'Falling costs of renewable energy technologies'], effects: ['Solar and wind became cheapest electricity sources in many regions', 'Electric vehicle adoption accelerating globally'], places: ['Germany', 'China', 'United States'], frameworks: ['Environmental History', 'Innovation & Technology'] },
  '672': { slug: 'climate-action-movement', name: 'Climate Action Movement', label: 'Movement', era: 'Contemporary', summary: 'The global movement demanding urgent action on climate change, from Rio Earth Summit (1992) through the Paris Agreement (2015) to Greta Thunberg\'s School Strike for Climate (2018). Combining scientific advocacy, youth activism, policy campaigns, and legal action, the climate movement represents the largest coordinated environmental effort in human history.', causes: ['Scientific consensus on anthropogenic climate change', 'Visible impacts: extreme weather, melting ice, rising seas'], effects: ['Paris Agreement committed 196 nations to emissions targets', 'Youth climate strikes mobilized millions worldwide'], places: ['Paris', 'Sweden', 'Global'], frameworks: ['Environmental History', 'Cause & Effect'] },
  '673': { slug: 'animal-rights-movement', name: 'Animal Rights Movement', label: 'Movement', era: 'Contemporary', summary: 'The movement asserting that animals have inherent rights and should not be treated as property or resources. From Peter Singer\'s Animal Liberation (1975) to organizations like PETA and the Great Ape Project, the movement has influenced legislation on factory farming, animal testing, wildlife trade, and the philosophical status of non-human animals.', causes: ['Peter Singer\'s utilitarian argument against speciesism', 'Growing awareness of factory farming and animal testing conditions'], effects: ['Transformed regulations on animal testing and factory farming', 'Influenced dietary choices and consumer behavior worldwide'], places: ['Australia', 'United States', 'England'], frameworks: ['Cause & Effect', 'Environmental History'] },

  // Class 7 — Artifacts & Texts
  '762': { slug: 'winged-victory-samothrace', name: 'Nike of Samothrace (Winged Victory)', label: 'Text', era: 'Classical', summary: 'A Hellenistic marble sculpture (c. 200-190 BCE) depicting Nike, the Greek goddess of victory, alighting on the prow of a ship. Discovered on Samothrace in 1863, its dramatic pose, wind-swept drapery, and monumental scale make it one of the greatest masterpieces of ancient sculpture and a symbol of triumphant achievement, now at the Louvre.', causes: ['Hellenistic tradition of dynamic, emotionally expressive sculpture', 'Likely commemorating a naval victory'], effects: ['Became one of the most recognized artworks in Western tradition', 'Influenced modern representations of victory and achievement'], places: ['Samothrace', 'Greece', 'Paris'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '763': { slug: 'beethovens-ninth-symphony', name: 'Beethoven\'s Ninth Symphony', label: 'Text', era: 'Modern', summary: 'Ludwig van Beethoven\'s final complete symphony (1824), revolutionary for incorporating vocal soloists and chorus (Schiller\'s "Ode to Joy") into a symphonic work. Composed while Beethoven was nearly deaf, the Ninth expanded the boundaries of orchestral music and its "Ode to Joy" theme was adopted as the anthem of the European Union, symbolizing universal brotherhood.', causes: ['Beethoven\'s desire to set Schiller\'s ode to music since youth', 'Romantic era\'s expansion of symphonic scale and ambition'], effects: ['Set standard for orchestral ambition in the Romantic era', 'Ode to Joy adopted as anthem of the European Union'], places: ['Vienna', 'Austria', 'Europe'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '764': { slug: 'hagia-sophia-architecture', name: 'Hagia Sophia', label: 'Text', era: 'Medieval', summary: 'A monumental architectural masterpiece in Istanbul, originally built as a Byzantine Christian cathedral (537 CE) under Emperor Justinian I. Its massive dome (31 meters diameter) was an engineering marvel unmatched for nearly a millennium. Converted to a mosque after 1453, it served as the model for Ottoman mosque architecture and remains one of the most significant buildings in world history.', causes: ['Emperor Justinian\'s ambition to build the greatest church in Christendom', 'Byzantine engineering innovations in pendentive dome construction'], effects: ['Model for Ottoman mosque architecture for centuries', 'Symbol of cultural transition from Byzantine to Ottoman civilization'], places: ['Istanbul', 'Turkey'], frameworks: ['Cultural Diffusion', 'Innovation & Technology'] },
  '772': { slug: 'damascus-steel-weapons', name: 'Damascus Steel', label: 'Text', era: 'Medieval', summary: 'A legendary type of steel used in swords and blades from the Near East, characterized by distinctive wavy patterns (watered steel) and exceptional sharpness and durability. Produced using wootz crucible steel from India, Damascus blades were prized throughout the medieval world and their metallurgical secrets — involving carbon nanotubes — were only recently understood by modern science.', causes: ['Indian wootz steel trading along Silk Road', 'Middle Eastern smithing techniques perfecting the material'], effects: ['Set standard for blade quality in medieval warfare', 'Modern analysis revealed carbon nanotubes explaining properties'], places: ['Damascus', 'Syria', 'India'], frameworks: ['Innovation & Technology', 'Cultural Diffusion'] },
  '773': { slug: 'zheng-he-treasure-ships', name: 'Zheng He\'s Treasure Ships', label: 'Text', era: 'Medieval', summary: 'The massive wooden ships (up to 120 meters long) of Admiral Zheng He\'s seven maritime expeditions (1405-1433) under the Ming dynasty, the largest wooden vessels ever built. These treasure fleets — carrying up to 28,000 crew — projected Chinese power across Southeast Asia, India, Arabia, and East Africa, representing the peak of pre-modern maritime technology.', causes: ['Ming dynasty desire to project power and expand tribute system', 'Chinese advances in shipbuilding, navigation, and gunpowder'], effects: ['Established Chinese maritime presence across Indian Ocean', 'Abrupt cancellation ended potential Chinese Age of Exploration'], places: ['China', 'Southeast Asia', 'East Africa'], frameworks: ['Innovation & Technology', 'Empire & Colonialism'] },
  '783': { slug: 'tale-of-genji-novel', name: 'The Tale of Genji', label: 'Text', era: 'Medieval', summary: 'Written by Murasaki Shikibu in early 11th-century Japan, The Tale of Genji is widely considered the world\'s first novel. This 54-chapter narrative of court life, romantic intrigue, and psychological depth in Heian-period Japan established literary techniques — interior monologue, character development, narrative structure — that anticipate the modern novel by 800 years.', causes: ['Sophisticated literary culture of Heian court women', 'Japanese kana script enabling women\'s literary expression'], effects: ['Considered the world\'s first novel', 'Foundational text of Japanese literary tradition'], places: ['Kyoto', 'Japan'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '814': { slug: 'anne-frank-diary-evidence', name: 'Diary of Anne Frank', label: 'Evidence', era: 'Contemporary', summary: 'The diary kept by Anne Frank (1929-1945), a Jewish girl hiding from Nazi persecution in Amsterdam, from June 12, 1942 to August 1, 1944. Published posthumously in 1947, the diary became the most widely read personal account of the Holocaust, translated into 70+ languages and read by tens of millions, humanizing the suffering of Holocaust victims.', causes: ['Nazi occupation of the Netherlands and persecution of Jews', 'Anne Frank\'s literary talent and desire to become a writer'], effects: ['Most widely read account of the Holocaust', 'Translated into 70+ languages, read by tens of millions'], places: ['Amsterdam', 'Netherlands', 'Bergen-Belsen'], frameworks: ['Cause & Effect', 'Cultural Diffusion'] },
  '815': { slug: 'herodotus-persian-wars-account', name: 'Herodotus\'s Account of the Persian Wars', label: 'Evidence', era: 'Classical', summary: 'The first major work of historical investigation, Herodotus\'s Histories (c. 440 BCE) is the primary eyewitness-adjacent account of the Greco-Persian Wars (499-449 BCE). By traveling to Egypt, Babylon, and Scythia to interview witnesses and examine evidence, Herodotus established the methodology of historical inquiry that earns him the title "Father of History."', causes: ['Herodotus\'s extensive travels collecting oral testimony', 'Greek victory in Persian Wars demanding explanation'], effects: ['Primary source for understanding Greco-Persian Wars', 'Established methodology of historical inquiry'], places: ['Greece', 'Egypt', 'Persia'], frameworks: ['Cause & Effect', 'Cultural Diffusion'] },
  '821': { slug: 'decline-fall-roman-empire', name: 'Decline and Fall of the Roman Empire (Gibbon)', label: 'Evidence', era: 'Early Modern', summary: 'Edward Gibbon\'s six-volume History of the Decline and Fall of the Roman Empire (1776-1789), covering 1,500 years from Trajan to the fall of Constantinople (1453). Gibbon\'s work established the modern historical method of critical source analysis and remains the most influential work of historiography in the English language.', causes: ['Enlightenment interest in understanding civilizational decline', 'Gibbon\'s encounter with Roman ruins inspiring the project'], effects: ['Established modern standards of historical scholarship', 'Popularized the narrative of Roman decline still debated today'], places: ['Rome', 'England', 'Constantinople'], frameworks: ['Cause & Effect', 'Empire & Colonialism'] },
  '822': { slug: 'lancet-medical-journal', name: 'The Lancet', label: 'Evidence', era: 'Modern', summary: 'One of the world\'s oldest and most prestigious peer-reviewed medical journals, founded in 1823 by Thomas Wakley. The Lancet pioneered the publication of clinical research, public health investigations, and medical ethics debates, establishing the peer-reviewed journal as the primary vehicle for communicating scientific medical knowledge.', causes: ['Need for reliable communication of medical discoveries', 'Thomas Wakley\'s reform campaign against medical establishment'], effects: ['Established model for peer-reviewed medical publishing', 'Published landmark studies shaping global health policy'], places: ['London', 'England', 'Global'], frameworks: ['Innovation & Technology', 'Institutional Analysis'] },
  '823': { slug: 'encyclopedie-diderot', name: 'Encyclopedie (Diderot & d\'Alembert)', label: 'Evidence', era: 'Early Modern', summary: 'The Encyclopedie, ou dictionnaire raisonne des sciences, des arts et des metiers (1751-1772), edited by Denis Diderot and Jean le Rond d\'Alembert — the most ambitious reference work of the Enlightenment. Its 28 volumes compiled knowledge across all disciplines through a rationalist, secular lens, challenging religious authority and helping lay the intellectual groundwork for the French Revolution.', causes: ['Enlightenment ambition to systematize all human knowledge', 'French intellectual culture producing a community of philosophes'], effects: ['Spread Enlightenment ideas across Europe', 'Helped lay intellectual groundwork for the French Revolution'], places: ['Paris', 'France'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '832': { slug: 'elgin-marbles-analysis', name: 'Elgin Marbles (Parthenon Sculptures)', label: 'Evidence', era: 'Classical', summary: 'A collection of classical Greek marble sculptures, inscriptions, and architectural elements from the Parthenon and other buildings on the Athenian Acropolis, removed by Lord Elgin in 1801-1812 and now in the British Museum. Their study has been fundamental to understanding Athenian art, religion, and society, while their ownership remains one of the most contentious cultural heritage disputes.', causes: ['Lord Elgin\'s acquisition of sculptures from Ottoman-controlled Athens', 'British Museum\'s preservation and display since 1816'], effects: ['Fundamental to modern understanding of classical Greek art', 'Central case in global debates on cultural heritage repatriation'], places: ['Athens', 'Greece', 'London'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '833': { slug: 'radiocarbon-dating-evidence', name: 'Radiocarbon Dating Method', label: 'Evidence', era: 'Contemporary', summary: 'A radiometric dating method developed by Willard Libby in 1949 that measures the decay of carbon-14 to determine the age of organic materials up to about 50,000 years old. Radiocarbon dating revolutionized archaeology, geology, and paleontology by providing the first reliable absolute dating method, earning Libby the 1960 Nobel Prize in Chemistry.', causes: ['Libby\'s insight that cosmic ray-produced C-14 could serve as a clock', 'Development of sensitive mass spectrometry equipment'], effects: ['Revolutionized archaeological and geological dating', 'Enabled precise chronologies for prehistoric civilizations'], places: ['Chicago', 'United States', 'Global'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '840': { slug: 'quantitative-data-overview', name: 'Quantitative Data in Historical Research', label: 'Evidence', era: 'Modern', summary: 'The use of numerical data — census records, economic statistics, demographic measurements, and computational analysis — to study historical patterns. From the Domesday Book to modern cliometrics and big data approaches, quantitative methods have transformed history from purely narrative to analytically rigorous, revealing patterns invisible to traditional scholarship.', causes: ['State censuses generating population and economic data', 'Development of statistical methods applicable to historical questions'], effects: ['Enabled cliometrics and economic history as rigorous disciplines', 'Big data approaches now revealing large-scale historical patterns'], places: ['England', 'France', 'United States'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '843': { slug: 'gis-historical-mapping', name: 'Geographic Information Systems (GIS) for History', label: 'Evidence', era: 'Contemporary', summary: 'The application of geospatial technology to historical research, enabling scholars to map and analyze spatial patterns in historical data. From reconstructing ancient trade routes to mapping plague spread and demographic shifts, historical GIS has created a new field of spatial history that reveals patterns invisible in traditional text-based sources.', causes: ['Development of digital mapping and GIS software', 'Digitization of historical maps, records, and spatial data'], effects: ['Created spatial history as a recognized subdiscipline', 'Enabled visualization of historical patterns across geography and time'], places: ['Stanford', 'United States', 'Global'], frameworks: ['Innovation & Technology', 'Cause & Effect'] },
  '850': { slug: 'oral-traditions-overview', name: 'Oral Traditions as Historical Evidence', label: 'Evidence', era: 'Prehistoric', summary: 'The transmission of cultural knowledge, histories, laws, and identities through spoken word across generations. Before writing, all human knowledge was oral. Even after literacy, oral traditions — griots in West Africa, Aboriginal Dreamtime narratives, Polynesian genealogies — preserved histories spanning thousands of years with remarkable accuracy, now recognized as valid historical evidence.', causes: ['Pre-literate societies requiring non-written knowledge preservation', 'Cultural practices embedding history in song, ritual, and performance'], effects: ['Preserved histories spanning thousands of years before writing', 'Increasingly recognized as valid evidence in scholarly research'], places: ['West Africa', 'Australia', 'Polynesia'], frameworks: ['Cultural Diffusion', 'Comparative Religion'] },
  '853': { slug: 'whakapapa-genealogies', name: 'Whakapapa (Maori Genealogies)', label: 'Evidence', era: 'Medieval', summary: 'The Maori genealogical system that traces descent lines from the gods through founding ancestors to living persons, serving simultaneously as history, law, identity, and spiritual connection. Whakapapa demonstrates how oral genealogical records can preserve centuries of demographic, political, and migration information with remarkable accuracy, confirmed by DNA evidence.', causes: ['Polynesian tradition of genealogical recitation', 'Genealogy serving as legal basis for land and resource rights'], effects: ['Preserved centuries of Maori migration and political history', 'Modern DNA studies confirming accuracy of oral genealogical records'], places: ['New Zealand', 'Polynesia'], frameworks: ['Cultural Diffusion', 'Comparative Religion'] },

  // Class 9 — Timeframes
  '910': { slug: 'prehistoric-era-overview', name: 'The Prehistoric Era', label: 'EventWindow', era: 'Prehistoric', summary: 'The vast span of human existence before the invention of writing (c. 3200 BCE in Mesopotamia), encompassing over 99% of human history. From the earliest stone tools (3.3 million years ago) through the agricultural revolution (c. 10,000 BCE), prehistoric peoples developed language, art, religion, agriculture, and social organization — the foundations of all subsequent civilization.', causes: ['Evolution of Homo sapiens in East Africa', 'Development of language and symbolic thought'], effects: ['Agricultural revolution enabled sedentary civilizations', 'Oral traditions preserved knowledge for millennia before writing'], places: ['East Africa', 'Fertile Crescent', 'Global'], frameworks: ['Environmental History', 'Innovation & Technology'] },
  '912': { slug: 'neolithic-revolution-era', name: 'Neolithic Revolution Period', label: 'EventWindow', era: 'Prehistoric', summary: 'The period (c. 10,000-3,000 BCE) when humans transitioned from nomadic hunting-gathering to settled agricultural communities, independently in at least seven world regions. This "first economic revolution" — domesticating plants and animals — enabled population growth, permanent settlements, social stratification, craft specialization, and eventually cities, states, and writing.', causes: ['Post-Ice Age climate warming enabling plant cultivation', 'Population pressure on wild food resources'], effects: ['Permanent settlements leading to first cities', 'Social stratification and earliest forms of government'], places: ['Fertile Crescent', 'China', 'Mesoamerica'], frameworks: ['Environmental History', 'Economic Systems'] },
  '921': { slug: 'archaic-greece-period', name: 'Archaic Greek Period', label: 'EventWindow', era: 'Classical', summary: 'The period of ancient Greek history (c. 800-480 BCE) between the Dark Ages and the Classical period, during which the Greeks developed the polis (city-state), alphabetic writing, monumental architecture, Olympic games, philosophical inquiry, and colonized the Mediterranean from Spain to the Black Sea — laying the foundations of Western civilization.', causes: ['Recovery from Bronze Age collapse and Greek Dark Ages', 'Phoenician alphabet adopted and modified for Greek language'], effects: ['Created the polis as foundational political unit', 'Greek colonization spread Hellenic culture across Mediterranean'], places: ['Greece', 'Athens', 'Corinth'], frameworks: ['Cultural Diffusion', 'Political Systems'] },
  '922': { slug: 'hellenistic-period-era', name: 'Hellenistic Period', label: 'EventWindow', era: 'Classical', summary: 'The era (323-31 BCE) from Alexander the Great\'s death to Rome\'s annexation of Egypt, during which Greek culture spread across the Near East, Central Asia, and North Africa. Hellenistic kingdoms blended Greek and local traditions, producing advances in science (Euclid, Archimedes), philosophy (Stoicism, Epicureanism), and art that profoundly influenced Roman and later Western culture.', causes: ['Alexander the Great\'s conquests spreading Greek culture', 'Division of Alexander\'s empire among successor generals'], effects: ['Blended Greek and Eastern cultures across vast territories', 'Scientific and philosophical advances at Alexandria and Pergamon'], places: ['Alexandria', 'Antioch', 'Pergamon'], frameworks: ['Cultural Diffusion', 'Empire & Colonialism'] },
  '924': { slug: 'late-antiquity-period', name: 'Late Antiquity', label: 'EventWindow', era: 'Classical', summary: 'The transitional period (c. 250-750 CE) between the Classical world and the Middle Ages, encompassing the decline of the Western Roman Empire, the rise of Christianity and Islam, the Germanic migrations, and the emergence of the Byzantine, Sassanid, and early Islamic civilizations. Modern scholarship views Late Antiquity as a period of transformation rather than simple decline.', causes: ['Internal pressures on the Roman Empire: military, economic, demographic', 'Rise of Christianity as state religion of the Roman Empire'], effects: ['Transition from Classical to Medieval civilizational patterns', 'Emergence of three successor civilizations: Byzantine, Islamic, Western European'], places: ['Rome', 'Constantinople', 'Mecca'], frameworks: ['Cause & Effect', 'Doctrine Development'] },
  '930': { slug: 'medieval-era-overview', name: 'The Medieval Period', label: 'EventWindow', era: 'Medieval', summary: 'The period of European and global history (c. 500-1500 CE) between the fall of Rome and the Renaissance, characterized by feudalism, the Catholic Church\'s dominance, Islamic Golden Age, Mongol expansion, and the gradual development of institutions — universities, parliaments, banking — that would enable the modern world.', causes: ['Collapse of Western Roman Empire and political fragmentation', 'Rise of Christianity and Islam as organizing civilizational forces'], effects: ['Created institutional foundations for modern Europe', 'Islamic Golden Age preserved and advanced classical knowledge'], places: ['Paris', 'Baghdad', 'Constantinople'], frameworks: ['Institutional Analysis', 'Doctrine Development'] },
  '940': { slug: 'early-modern-era-overview', name: 'The Early Modern Period', label: 'EventWindow', era: 'Early Modern', summary: 'The period (c. 1500-1800) encompassing the Renaissance, Reformation, Age of Exploration, Scientific Revolution, and Enlightenment — when Europe\'s intellectual, commercial, and military expansion reshaped global power relations. Printing, gunpowder, and oceanic navigation compressed distance and accelerated the exchange of ideas, goods, and microbes across civilizations.', causes: ['Fall of Constantinople driving Western exploration of alternate routes', 'Printing press enabling rapid dissemination of knowledge'], effects: ['European colonial empires spanning all continents', 'Scientific Revolution establishing empirical method'], places: ['Europe', 'Americas', 'Asia'], frameworks: ['Empire & Colonialism', 'Innovation & Technology'] },
  '942': { slug: 'renaissance-period-era', name: 'The Renaissance Period', label: 'EventWindow', era: 'Early Modern', summary: 'The cultural and intellectual "rebirth" (c. 1350-1600) originating in Italian city-states, characterized by renewed interest in classical antiquity, humanist philosophy, artistic innovation, and scientific inquiry. The Renaissance produced Leonardo, Michelangelo, Machiavelli, and Copernicus, transforming European art, science, politics, and self-understanding.', causes: ['Italian city-state wealth from Mediterranean trade', 'Recovery of classical Greek and Roman texts via Arabic translations'], effects: ['Transformed European art, science, and philosophy', 'Humanist education became foundation of Western liberal arts'], places: ['Florence', 'Rome', 'Venice'], frameworks: ['Cultural Diffusion', 'Cause & Effect'] },
  '952': { slug: 'new-imperialism-era', name: 'Age of Empire / New Imperialism', label: 'EventWindow', era: 'Modern', summary: 'The period (c. 1870-1914) when European powers, the United States, and Japan rapidly colonized most of Africa, Asia, and the Pacific. Driven by industrial capitalism, nationalism, racial ideology, and strategic competition, the New Imperialism brought 85% of the world under Western domination and created global inequalities whose effects persist today.', causes: ['Industrial Revolution producing surplus capital seeking overseas investment', 'Nationalist competition among European powers'], effects: ['85% of world\'s surface under Western control by 1914', 'Created economic and political structures shaping post-colonial nations'], places: ['Africa', 'Southeast Asia', 'Pacific'], frameworks: ['Empire & Colonialism', 'Economic Systems'] },
  '954': { slug: 'world-war-ii-era', name: 'World War II Era', label: 'EventWindow', era: 'Contemporary', summary: 'The most devastating conflict in human history (1939-1945), involving 61 countries, 1.7 billion people, and resulting in 70-85 million deaths including the Holocaust. The war destroyed European colonial empires, created the United Nations and Cold War bipolar order, generated nuclear weapons, and established the United States as a superpower — reshaping every aspect of the modern world.', causes: ['Rise of fascism in Germany, Italy, and Japan', 'Failure of appeasement and League of Nations collective security'], effects: ['Created the United Nations and post-war international order', 'Launched nuclear age and Cold War'], places: ['Europe', 'Pacific', 'Global'], frameworks: ['Cause & Effect', 'Political Systems'] },
  '962': { slug: 'post-cold-war-globalization', name: 'Post-Cold War & Globalization Era', label: 'EventWindow', era: 'Contemporary', summary: 'The period since the fall of the Berlin Wall (1989) and Soviet dissolution (1991), characterized by American unipolarity, economic globalization, digital revolution, and the rise of China and India. This era saw the spread of democracy, free markets, and the internet alongside new challenges: terrorism, climate change, populism, and great-power competition.', causes: ['Soviet Union collapse ending Cold War bipolar order', 'Digital revolution and economic liberalization accelerating globalization'], effects: ['Rapid economic growth lifted billions from poverty', 'Rise of China as second superpower challenging Western dominance'], places: ['United States', 'China', 'European Union'], frameworks: ['Economic Systems', 'Political Systems'] },
};

