const newSlugs = new Map<string, string>();
const internalDupes: string[] = [];
Object.entries(entityDefs).forEach(([code, def]) => {
  if (newSlugs.has(def.slug)) {
    internalDupes.push(`${def.slug} (${newSlugs.get(def.slug)} vs ${code})`);
  }
  newSlugs.set(def.slug, code);
});
if (internalDupes.length > 0) {
  console.error(`ERROR: Internal duplicate slugs: ${internalDupes.join(', ')}`);
  process.exit(1);
}

console.log(`All ${Object.keys(entityDefs).length} entities validated. Generating TypeScript...`);

// Generate the output file
const lines: string[] = [];
lines.push(`/**`);
lines.push(` * Division Gap Fill — ${Object.keys(entityDefs).length} entities covering all previously empty divisions.`);
lines.push(` * Auto-generated by scripts/generate-gap-entities.ts`);
lines.push(` * DO NOT EDIT MANUALLY — regenerate with: npx tsx scripts/generate-gap-entities.ts`);
lines.push(` */`);
lines.push(`import type { Entity } from '../entityTypes'`);
lines.push(``);
lines.push(`export const divisionGapFillEntities: Entity[] = [`);

Object.entries(entityDefs).forEach(([code, def]) => {
  const divInfo = DIVISIONS.find(d => d.code === code)!;
  const cls = parseInt(code[0]);
  // Get next available serial for this division
  const serial = '01';
  const callNumber = `${code}.${serial}-${def.slug}`;

  lines.push(`  {`);
  lines.push(`    slug: '${def.slug}',`);
  lines.push(`    name: '${def.name.replace(/'/g, "\\'")}',`);
  lines.push(`    label: '${def.label}',`);
  lines.push(`    callNumber: '${callNumber}',`);
  lines.push(`    era: '${def.era}',`);
  lines.push(`    summary: ${JSON.stringify(def.summary)},`);
  lines.push(`    causes: ${JSON.stringify(def.causes)},`);
  lines.push(`    effects: ${JSON.stringify(def.effects)},`);
  lines.push(`    relationships: [`);
  def.places.forEach(p => {
    lines.push(`      { type: 'OCCURS_IN', target: '${p.toLowerCase().replace(/[^a-z0-9]+/g, '-')}' },`);
  });
  lines.push(`    ],`);
  lines.push(`    subjects: ${JSON.stringify([divInfo.heading, ...def.places])},`);
  lines.push(`    subjectHeadings: ['${def.label} — ${divInfo.heading} — ${def.era}'],`);
  lines.push(`    frameworks: ${JSON.stringify(def.frameworks)},`);
  lines.push(`    places: ${JSON.stringify(def.places)},`);
  lines.push(`    texts: [],`);
  lines.push(`  },`);
});

lines.push(`]`);

const outPath = path.resolve(__dirname, '../src/data/catalog/divisionGapFill.ts');
fs.writeFileSync(outPath, lines.join('\n') + '\n', 'utf8');
console.log(`Wrote ${outPath}`);
console.log(`Entity count: ${Object.keys(entityDefs).length}`);
